// :octopus:
#define C(a, e) cross(a - d, e - d).z//
#define F(e) C(u, e) * C(a, e) > 0. ?//
#define A T, a=b, b=c, c=d
void mainImage(out vec4 o, vec2 U) 
{
    vec3 u, a, b, c, d, e, G = u + .618;
    u.xy = U / iResolution.y; 
    int T, i;
    b.x = 5.; a = -b; 
    for(c.y = 3.6; i++ < 9; d=c)   
        if (T < 1)        
            e = a - a * G,
            d = e + b * G,
            e += c * G,
            F(e)      b=a, a=d, c=e :
            F(c) ++A, a=e :
                     (A);                
        else
            d += (a - c) * G,
            F(b)      c=b, b=a, a=d : 
                (--A); 
     o = max(.3 * vec4(0, ++T, G), 
             1.2 - 2e3 * min(abs(C(u, a)),abs(C(u, b))));
}



