/*
// thanks to FabriceNeyret2 658 chars from (>961 chars)
// I’ve absorbed quite a few improvement methods from @FabriceNeyret2
//
// L(b): Draw a straight line passing through two points: (c) and (b+c). 
// B(e): Compare whether point (a) and point (u) are on the same side of the line (ed).

//#define H    , b=c, c=d  // -1 chars

// Improvement: Use the cross product magnitude principle (|a||b|sin(theta)) to calculate the distance from a point to a line. Since it is parallel to the coordinate axis, the z-component length can be directly taken as the result.
#define L(b) abs(cross(u-c,b).z)//                 
#define B(e) ( cross(a-d,e-d) * cross(u-d,e-d) ).z > 0. ?//

void mainImage(out vec4 o, vec2 U)
{
        vec3 u ,  a, b, c, d, e;              
        u.xy = U / iResolution.y;
        float G = .618, T,i;      

        o *= i;

        b.x = 5., a = -b;  // triangle a b c

        for( c.y = 3.6 ; i++<9.; )                     
                if(T<.5)
                        d = a + (b - a) * G,
                        e = a + (c - a) * G,                                                      
                          B(e)       b=a, a=d, c=e
                        : B(c)  T++, a=e, b=c, c=d
                        :          ( a=b, b=c, c=d );
                else
                        d = c + (a - c) * G,                                               
                          B(b)       c=b, b=a, a=d
                        :     ( T--, a=b, b=c, c=d );                        
        o.g = ++T*.3;
        o = max(o, 1.2-2e3*min(L(a-c), L(b-c)));// 388ch   orginal:1.-1e3* 
        //o = max(vec4(0,++T*.3,0,0), 2e-4/min(L(a-c), L(b-c))); // 385ch
        //o = o*0. + max(++T*.3, 1.-2e3*min(L(a-c), L(b-c)));    // 380
        //o = o*0. + max(++T*.3, 9e-5/min(L(a-c), L(b-c)));      // 378      
}





